import functools
import inspect
from typing import ForwardRef, Any, Dict, Callable
from fastapi.dependencies.utils import get_typed_signature, get_typed_annotation

# We need to simulate a scenario where the wrapped function's globals
# do not contain the type used in the forward reference.

def create_original_func():
    # This function will be defined in a way that it has its own globals
    # (simulated by using a closure or just defining it here)

    # In a real scenario, this would be in another module.
    # Since we are in one script, we can use a trick.

    def original_func(a: "MyModel"):
        return a

    # We manually add MyModel to the globals of original_func
    original_func.__globals__["MyModel"] = type("MyModel", (), {})
    return original_func

original_func = create_original_func()

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

wrapped_func = wrapper(original_func)

# wrapped_func.__globals__ is the globals of this module.
# original_func.__globals__ is also the globals of this module because of how I did it.

# Let's try to make them different.
def wrapper_in_another_scope(func):
    def wrapper_scope():
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped
    return wrapper_scope()

wrapped_func = wrapper_in_another_scope(original_func)

# Now wrapped_func is defined inside wrapper_scope, so its __globals__ 
# should be the globals of the module where wrapper_in_another_scope is defined.
# Wait, that's still the same module.

try:
    sig = get_typed_signature(wrapped_func)
    print("Success!")
    print(sig)
except Exception as e:
    print(f"Error: {e}")
    import traceback
    traceback.print_exc()

